	if storeErr != nil || len(stored.Evidence) != 0 {
		t.Fatalf("rejected evidence was recorded anyway: %#v, %v", stored, storeErr)
	}
}

// TestCompleteClaimValidatesOutputAsTheInProcessPathDoes is the "not weaker"
// requirement. A remote worker must not be able to record output that an
// in-process executor could not.
func TestCompleteClaimValidatesOutputAsTheInProcessPathDoes(t *testing.T) {
	fixture := newCompletionFixture(t, EffectExternal)

	request := fixture.completion()
	// The declared OutputSchema requires a boolean "ok" and forbids anything
	// else.
	request.Result.Output = json.RawMessage(`{"ok":"yes","extra":1}`)
	completed, err := fixture.service.CompleteClaim(fixture.ctx, request)
	if err == nil {
		t.Fatal("schema-violating output was accepted")
	}
	if completed.State != DispatchFailed || completed.ErrorCode != "invalid_executor_output" {
		t.Fatalf("invalid output record = %#v", completed)
	}
	stored, storeErr := fixture.store.GetAction(fixture.ctx, fixture.claimed.ID)
	if storeErr != nil || stored.State != DispatchFailed {
		t.Fatalf("stored = %#v, %v", stored, storeErr)
	}
	if len(stored.Output) != 0 {
		t.Fatalf("the rejected output was recorded anyway: %s", stored.Output)
	}
}

// TestExecuteClaimStillRequiresARunnableExecutor is the other half: relaxing
// the requirement for claim and completion must not let in-process execution
// run against a reference that cannot run anything.
func TestExecuteClaimStillRequiresARunnableExecutor(t *testing.T) {
	fixture := newCompletionFixtureWithExecutor(t, EffectExternal, remoteOnlyExecutor{})

	if _, err := fixture.service.ExecuteClaim(fixture.ctx, fixture.claimed); err == nil {
		t.Fatal("ExecuteClaim ran an action whose executor has no Execute method")
	}
}

// TestRemoteExecutorNeedsNoInProcessExecute is the topology this whole change
// exists for. A gateway proxy performs its work itself and reports through
// CompleteClaim; nothing in this process ever runs it.
//
// Requiring it to supply an Execute method would make every remote deployment
// bind a stub whose only purpose is to be refused, so claim and completion
// resolve through resolveActionBinding. The effect ceiling is still enforced —
// the reference below declares EffectExternal, and an evidence-only one would
// still refuse this action.
func TestRemoteExecutorNeedsNoInProcessExecute(t *testing.T) {
	fixture := newCompletionFixtureWithExecutor(t, EffectExternal, remoteOnlyExecutor{})

	if !fixture.claimed.EffectPossible {
		t.Fatal("claiming an external action through a remote-only reference " +
			"did not mark the effect possible")
	}
	completed, err := fixture.service.CompleteClaim(fixture.ctx, fixture.completion())
	if err != nil {
		t.Fatalf("CompleteClaim through a remote-only executor: %v", err)
	}
	if completed.State != DispatchSucceeded {
		t.Fatalf("state = %q, want %q", completed.State, DispatchSucceeded)
	}
}

func newCompletionFixture(t *testing.T, effect Effect) *completionFixture {
	t.Helper()
	return newCompletionFixtureWithExecutor(t, effect, &remoteBoundExecutor{})
}

func newCompletionFixtureWithExecutor(t *testing.T, effect Effect, executor any) *completionFixture {
	t.Helper()
	now := time.Date(2026, 9, 6, 12, 0, 0, 0, time.UTC)
	clock := now
	authority, err := auth.NewAuthorityWithClock(func() time.Time { return now })
	if err != nil {
		t.Fatal(err)
	}
	registryStore := newMemoryStore()
	registry, err := NewService(Config{
		Store: registryStore, Resolver: authority.Resolver(), Recorder: &memoryRecorder{},
		Snapshots: fixedSnapshot{now},
		Executors: executorMap{"exec": executor},
		Clock:     func() time.Time { return clock },
	})
	if err != nil {
		t.Fatal(err)
	}
	descriptor := dispatchDescriptor(now)
	descriptor.Capabilities[0].Actions[0].Effect = effect
	// The shared descriptor's lease and the enqueued action's deadline both sit
	// one hour out, so advancing the clock far enough to expire the action
	// deadline expires the agent lease first and the action is refused as
	// not-found before its deadline is ever consulted. A longer lease keeps the
	// two bounds independent, which is what lets the deadline case below test
	// the deadline.
	descriptor.LeaseExpiresAt = now.Add(24 * time.Hour)
	registryStore.records["agent"] = Stored{Descriptor: descriptor}
	store := newMemoryDispatchStore()
	service, err := NewDispatchService(DispatchConfig{
		Store: store, Registry: registry, Resolver: authority.Resolver(),
		Recorder: &dispatchRecorder{}, Events: dispatchEvents{},
		Clock: func() time.Time { return clock },
	})
	if err != nil {
		t.Fatal(err)
	}
	decision := dispatchDecision(t, "owner", "actor", "request",
		auth.OperationDispatch, auth.OperationInvoke)
	ctx := bindDecision(t, authority, decision)
	queued, err := service.Enqueue(ctx, dispatchEnqueue(now, "request"))
	if err != nil {
		t.Fatal(err)
	}
	claimed, err := service.Claim(ctx, ClaimRequest{
		ID: queued.ID, ExpectedVersion: queued.Version, ClaimID: []byte("claim"),
		Lease: time.Minute, Context: dispatchContext(now, "request"),
	})
	if err != nil {
		t.Fatal(err)
	}
	return &completionFixture{
		service: service, store: store, authority: authority,
		claimed: claimed, ctx: ctx, clock: &clock,
	}
}

// completionFixture is a dispatch service with one claimed action, built for
// the remote path: no executor ever runs, because the point of CompleteClaim is
// that the work happened somewhere this process cannot see.
type completionFixture struct {
	service   *DispatchService
	store     *memoryDispatchStore
	authority *auth.Authority
	claimed   ActionRecord
	ctx       context.Context
	// clock drives both the registry and the dispatch service, so advancing it
	// expires a claim lease.
	clock *time.Time
}

// remoteBoundExecutor is what a host binds for work performed out of process.
//
// The effect boundary (#381) still applies to the remote path: an action
// declaring an external effect cannot resolve to a reference whose ceiling is
// evidence-only, so the host must say that this reference may cause external
// effects. Completion does not bypass that — it is reached only through an
// action that already resolved.
//
// Execute is never called. A remote worker pulls and claims, performs the work
// itself, and reports through CompleteClaim; nothing in this process runs it.
// Calling it is a test failure rather than a no-op, so a test that accidentally
// takes the in-process path says so instead of quietly passing.
type remoteBoundExecutor struct{ executed bool }

// remoteOnlyExecutor is a reference bound for work performed out of process. It
// declares an effect ceiling and deliberately implements no Execute.
type remoteOnlyExecutor struct{}

// CompletionRequest is a remote worker reporting the outcome of work it
// performed out of process.
//
// It is bound to a claim, not to an action. ClaimID and ExpectedVersion must
// name the claim the reporter actually holds: a worker whose lease expired
// while it was working must be refused rather than allowed to overwrite
// whatever happened next, because by then the action may have been reclaimed
// and run again by someone else.
//
// Result carries exactly what an in-process ActionExecutor returns, and is
// validated identically. A remote worker cannot record output or evidence an
// in-process one could not.
type CompletionRequest struct {
	ID              []byte
	ExpectedVersion uint64
	// ClaimID must equal the claim currently held on the action.
	ClaimID []byte
	Result  ExecutionResult
	// Failed reports that the work did not succeed. Result.ErrorCode carries
	// the reason. The two are separate because a worker that fails with no
	// error code is a protocol error, not a success.
	Failed  bool
	Context RequestContext
}

func (s *DispatchService) Claim(ctx context.Context, request ClaimRequest) (ActionRecord, error) {
	ctx, cancel := s.deadline(ctx, request.Context)
	defer cancel()
	decision, now, err := s.begin(ctx, auth.OperationInvoke, request.Context)
	if err != nil {
		return ActionRecord{}, err
	}
	if err := validateOpaque("action ID", request.ID, false); err != nil {
		return ActionRecord{}, err
	}
	if err := validateOpaque("claim ID", request.ClaimID, false); err != nil {
		return ActionRecord{}, err
	}
	if request.ExpectedVersion == 0 || request.Lease <= 0 || request.Lease > MaxActionClaimTTL {
		return ActionRecord{}, shoal.NewError(shoal.ErrorInvalidArgument, "claim version or lease is invalid")
	}
	current, err := s.authorizedCurrent(ctx, decision, request.ID, auth.OperationInvoke, now)
	if err != nil {
		return ActionRecord{}, err
	}
	if current.Version != request.ExpectedVersion {
		if current.State == DispatchClaimed &&
			current.Version == request.ExpectedVersion+1 &&
			bytes.Equal(current.ClaimID, request.ClaimID) &&
			current.ClaimLease == request.Lease {
			if err := s.publishTransition(
				context.WithoutCancel(ctx), "action.claimed", current,
			); err != nil {
				return ActionRecord{}, errors.Join(ErrActionCommitted, err)
			}
			return cloneActionRecord(current), nil
		}
		return ActionRecord{}, ErrActionConflict
	}
	if current.State == DispatchClaimed && now.Before(current.ClaimLeaseUntil) {
		return ActionRecord{}, ErrActionConflict
	}
	if current.State.terminal() {
		return ActionRecord{}, ErrActionTerminal
	}
	if !now.Before(current.Deadline) {
		return ActionRecord{}, ErrClaimLost
	}
	// Resolved for the declared Effect, which decides whether claiming this
	// action already makes an effect possible.
	//
	// authorizedCurrent above has already resolved the action and refused a
	// descriptor revoked, re-registered or narrowed since it was queued, so
	// this adds no authorization — it is how the declaration is obtained, since
	// authorizedCurrent discards what it resolved.
	_, claimedAction, _, err := s.registry.resolveActionBinding(
		ctx, decision, current.AgentID, current.AgentGeneration,
		current.Capability, current.Action, current.SourceID, current.PolicyID,
		current.ObjectID, auth.OperationInvoke, now,
	)
	if err != nil {
		return ActionRecord{}, err
	}
	next := cloneActionRecord(current)
	next.Version++
	next.State = DispatchClaimed
	// An external-effect action is possibly-effected from the moment it is
	// claimed, not from the moment it is executed.
	//
	// An in-process executor sets this at execution because this process owns
	// the window between admission and effect. A remote worker owns that window
	// itself: once it holds the claim it may act at any time, and if it then
	// goes silent the record must not say the effect certainly did not happen.
	// Without this a lease that expires after the work was done is
	// indistinguishable from one that expired before it started.
	//
	// It is narrowed by the declaration from #381 rather than set for every
	// claim. An evidence-only action mutates nothing outside Shoal, so its
	// outcome is visible in Shoal's own record and needs no assumption.
	if claimedAction.Effect == EffectExternal {
		next.EffectPossible = true
	}
	next.ClaimID = append([]byte(nil), request.ClaimID...)
	next.ClaimFence++
	next.ClaimLease = request.Lease
	next.ClaimLeaseUntil = now.Add(request.Lease)
	if next.ClaimLeaseUntil.After(next.Deadline) {
		next.ClaimLeaseUntil = next.Deadline
	}
	next.UpdatedAt = now
	next.Actor = decision.Actor()
	next.TransitionRequestID = decision.RequestID()
	next.TransitionCorrelationID = decision.CorrelationID()
	next.AuthorizedOperations = canonicalOperations(append(
		next.AuthorizedOperations, decisionOperations(decision, auth.OperationInvoke)...))
	next.ExecutionFingerprint, err = auth.AuthorizationFingerprint(decision)
	if err != nil {
		return ActionRecord{}, err
	}
	next.ExecutionPolicyGeneration = decision.PolicyGeneration()
	next.ExecutionExpiresAt = decision.AuthenticationExpires()
	if err := s.recorder.RecordAction(ctx, ActionAudit{Phase: "claim_admission", Operation: auth.OperationInvoke, Record: next}); err != nil {
		return ActionRecord{}, errors.Join(ErrRecordingUnavailable, err)
	}
	stored, err := s.store.ApplyAction(ctx, DispatchMutation{
		Token:           transitionToken("claim", request.ID, request.ClaimID, next.Version),
		ExpectedVersion: current.Version, ExpectedFence: current.ClaimFence,
		TransitionKind: "action.claimed", Record: next,
	})
	if err != nil {
		return ActionRecord{}, err
	}
	if err := s.publishTransition(
		context.WithoutCancel(ctx), "action.claimed", stored,
	); err != nil {
		return ActionRecord{}, errors.Join(ErrActionCommitted, err)
	}
	return cloneActionRecord(stored), nil
}

