		return Descriptor{}, Action{}, nil, err
	}
	if len(decision.OnBehalfOf()) > 0 {
		if err := decision.AuthorizeObject(auth.OperationDelegate, resource, now); err != nil {
			return Descriptor{}, Action{}, nil, err
